// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface LabourFieldOut {
  field_id: number;
  code: string;
  label: string;
  section: "Admission" | "Delivery" | "Mother" | "Baby" | "Discharge";
  kind: "Text" | "Number" | "Choice" | "MultiChoice" | "YesNo" | "Date";
  choices: string[];
  unit: string | null;
  min_value: number | null;
  max_value: number | null;
  required: boolean;
  /** Required only when this column has when_value */
  when_code: string | null;
  when_value: string | null;
  /** Where a default column comes from (the Punjab HMIS manual's page, a PHC manual); null for the hospital's own */
  source: string | null;
  sort_order: number;
  is_active: boolean;
  row_version: number;
}

/** A column of the hospital's own in the labour register. Its code, kind and section never change. */
export interface LabourFieldIn {
  code: string;
  label: string;
  /** Baby: one value per baby; the others: one per delivery */
  section: "Admission" | "Delivery" | "Mother" | "Baby" | "Discharge";
  kind: "Text" | "Number" | "Choice" | "MultiChoice" | "YesNo" | "Date";
  /** Choice and MultiChoice only, at least one */
  choices?: string[];
  unit?: string | null;
  /** Number only */
  min_value?: number | null;
  max_value?: number | null;
  /** Always required before the entry is signed */
  required?: boolean;
  /** Required only when this other column (of the same entry, or the same baby) has when_value; not with required */
  when_code?: string | null;
  when_value?: string | null;
  sort_order?: number;
}

export interface LabourFieldPatch {
  label?: string | null;
  /** The whole list: choices are added, never removed */
  choices?: string[] | null;
  unit?: string | null;
  min_value?: number | null;
  max_value?: number | null;
  required?: boolean | null;
  when_code?: string | null;
  when_value?: string | null;
  sort_order?: number | null;
  /** false: switched off for new entries; past entries keep their values */
  is_active?: boolean | null;
  /** row_version as read */
  expected_version: number;
}

/** The labour register's columns, in order — GET /api/v1/maternity/labour-register/columns (who may call: holders of maternity.view or maternity.record or maternity.policy.manage). */
export function listColumns(query?: { include_inactive?: boolean }): Promise<LabourFieldOut[]> {
  return api<LabourFieldOut[]>("GET", withQuery(`/maternity/labour-register/columns`, query), undefined);
}

/** Add a column of the hospital's own to the labour register — POST /api/v1/maternity/labour-register/columns (who may call: holders of maternity.policy.manage). */
export function addColumn(body: LabourFieldIn): Promise<LabourFieldOut> {
  return api<LabourFieldOut>("POST", `/maternity/labour-register/columns`, body, { idempotent: true });
}

/** Relabel, reorder, extend the choices, require or switch off a column — PATCH /api/v1/maternity/labour-register/columns/{field_id} (who may call: holders of maternity.policy.manage). */
export function updateColumn(field_id: number, body: LabourFieldPatch): Promise<LabourFieldOut> {
  return api<LabourFieldOut>("PATCH", `/maternity/labour-register/columns/${field_id}`, body);
}
